// Run with:
//   node --import ./scripts/test-register.mjs --test src/editor/strudel-docs.test.js
//
// The committed docs index (hover docs, signature hints, autocomplete, the
// reference panel) must only describe things a pattern can actually call
// with the installed packages. It is generated by `pnpm gen:docs`; this
// catches it drifting — after a package upgrade, or after a regeneration
// that let names from a newer upstream slip in. No network involved.

import { test, describe, before } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { collectScopeNames } from "../../scripts/strudel-scope.mjs";

const docs = JSON.parse(
  readFileSync(new URL("./strudel-docs.json", import.meta.url), "utf8"),
);
const names = Object.keys(docs);

describe("strudel-docs.json", () => {
  let scope;
  before(async () => {
    scope = await collectScopeNames();
  });

  test("every documented name is callable in strasbeat's eval scope", () => {
    const unknown = names.filter(
      (n) => !scope.base.has(n) && !scope.optIn.has(n),
    );
    assert.deepEqual(
      unknown,
      [],
      "documented but not callable — regenerate with `pnpm gen:docs`",
    );
  });

  test("names that need an opt-in package say which one", () => {
    for (const name of names) {
      const expected = scope.base.has(name) ? undefined : scope.optIn.get(name);
      assert.equal(docs[name].requires, expected, name);
      if (expected) assert.ok(docs[name].doc.includes(expected), name);
    }
  });

  test("entries are well-formed", () => {
    for (const name of names) {
      const entry = docs[name];
      assert.match(name, /^[A-Za-z_$][\w$]*$/, `bad key ${JSON.stringify(name)}`);
      assert.ok(entry.doc, `${name} has no description`);
      assert.ok(Array.isArray(entry.params), name);
      assert.ok(Array.isArray(entry.examples), name);
      // Values (signals such as `sine`) are used bare; everything else is called.
      const expected = scope.values.has(name)
        ? name
        : `${name}(${entry.params.map((p) => (p.type ? `${p.name}: ${p.type}` : p.name)).join(", ")})`;
      assert.equal(entry.signature, expected);
    }
  });

  test("covers the everyday functions, upstream's and strasbeat's own", () => {
    for (const name of [
      // core
      "s", "n", "note", "stack", "seq", "cat", "fastcat", "stepcat", "ply",
      "pick", "fast", "slow", "every", "jux", "setcpm", "hush", "all",
      // editor widgets, samples, soundfonts
      "slider", "samples", "aliasBank",
      // opt-in packages
      "midi", "midin", "midikeys", "osc", "tune",
      // strasbeat extensions
      "progression", "arrange", "shader", "initHydra", "piano",
    ]) {
      assert.ok(Object.hasOwn(docs, name), `${name} is missing`);
    }
  });

  test("app-internal helpers stay out", () => {
    for (const name of [
      "primeArrangementParser", "subscribeRegistry", "resetRegistry",
      "beginEvaluate", "markEvalAppliedFor", "endEvaluate", "setSolo",
      "validateSolo", "constructor",
    ]) {
      assert.ok(!Object.hasOwn(docs, name), `${name} leaked into the docs`);
    }
  });
});
